mapper.select:
SELECT id,batch_id,batch_participant_id,batch_service_id,is_performed,service_request_id,unit_price_snapshot,recorded_by,recorded_at,created_at,updated_at,row_version
FROM public.health_examination_participant_services WHERE batch_participant_id IN #{id}
ORDER BY id

mapper.update:
UPDATE public.health_examination_batch_participants SET
 row_version=row_version+1,updated_at=CURRENT_TIMESTAMP,batch_day_id=#{p.batchDayId},patient_id=#{p.patientId},prepared_at=#{p.preparedAt},roster_status=#{p.rosterStatus},
 attendance_status=#{p.attendanceStatus},actual_examination_date=#{p.actualExaminationDate},attendance_recorded_by=#{p.attendanceRecordedBy},
 attendance_recorded_at=#{p.attendanceRecordedAt},attendance_note=#{p.attendanceNote},service_reconciliation_status=#{p.serviceReconciliationStatus},
 services_reconciled_by=#{p.servicesReconciledBy},services_reconciled_at=#{p.servicesReconciledAt}
 WHERE id=#{p.id} AND batch_id=#{p.batchId} AND row_version=#{expectedVersion}
